-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.creature_attack(p_world uuid, p_attacker integer, p_target integer)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
declare v_chance double precision; a creature; d species_def; v_dmg double precision; t creature; v_guard uuid; v_died boolean; v_used boolean;
begin
  select * into a from creature where world_id = p_world and id = p_attacker;
  if not found then return false; end if;
  -- A Sworn Blade's Guardian near a companion a wild thing strikes may take the blow on a shield instead.
  if a.mode = 'wild' then
    select * into t from creature where world_id = p_world and id = p_target;
    if t.id is not null and t.mode <> 'wild' then
      v_guard := class_guardian(p_world, creature_x(t), creature_y(t), null);
      if v_guard is not null then
        perform class_guard_take(p_world, v_guard, attack_of(a) * blow_share(),
          coalesce((select lower(name) from species_def where id = a.species), 'creature'), coalesce(t.name, 'a companion'));
        return false;
      end if;
    end if;
  end if;
  select * into d from species_def where id = a.species;
  select * into t from creature where world_id = p_world and id = p_target;
  if a.mode <> 'wild' and d.ability is not null then
    v_used := beast_ability(p_world, a, p_target);
    if v_used is not null then return v_used; end if;
  end if;
  -- Its blood has a say in what it lands for, as it does in what it bites you for.
  v_dmg := attack_of(a) * (1 + coalesce((a.skills->>'fighting')::double precision, 0) / 200)
           * (0.7 + random() * 0.6)
           -- And larger inside its keeper's Bloodlust and Primal Fury (`companion_dealt`).
           * companion_dealt(a)
           -- And less inside a Binder's Dull Claws (`class_dull`).
           * class_dull(p_world, p_attacker)
           -- And harder for how it fights: a borer on a hide, a flanker on one whose mind is elsewhere (`style_dealt`).
           * style_dealt(a, t);
  if a.skills ? 'fighting' then perform worker_learn(p_world, p_attacker, 'fighting', 0.05); end if;
  -- A heavy blow, at its blood's chance (`heavy`): `heavy_hit` as hard. The dice are thrown only for one that has a chance.
  v_chance := beast_chance(a, 'heavy');
  if v_chance > 0 then
    if random() < v_chance then v_dmg := v_dmg * heavy_hit(); end if;
  end if;
  v_died := wound_beast(p_world, p_target, v_dmg, creature_x(a), creature_y(a), null, p_attacker);
  if not v_died then perform style_blow(p_world, a, p_target, v_dmg); end if;
  -- And a bleed, at its blood's chance (`rip`), as a knife opens it; a kind whose bites bleed already bleeds it.
  if not v_died and (a.mode = 'wild' or d.style is distinct from 'bleed') then
    v_chance := beast_chance(a, 'rip');
    if v_chance > 0 then
      if random() < v_chance then
        update creature set bleed_rate = greatest(coalesce(bleed_rate, 0), v_dmg * knife_bleed()),
            bleed_until = now() + make_interval(secs => knife_bleed_secs())
          where world_id = p_world and id = p_target and health > 0;
      end if;
    end if;
  end if;
  -- Pushed off while a keep-away holds on what struck it (`pikeman_keep_away`).
  if not v_died and beast_mark(p_world, a.id, 'keep_away', 0) > 0 then
    perform class_shove(p_world, p_target, creature_x(a), creature_y(a), beast_mark(p_world, a.id, 'keep_away', 0));
  end if;
  -- And a Beastmaster's trade learns from it as from a blow of their own (`class_learn_beast`).
  perform class_learn_beast(p_world, a, v_died);
  return v_died;
end $function$
